# src/workpeg/run.py
import os
import subprocess
from pathlib import Path

from workpeg.build import build_image, validate_function_project
from workpeg.config import load_function_config


def resolve_runtime(with_runtime: str | None, config: dict) -> str:
    if with_runtime:
        return with_runtime
    return config.get("runtime", {}).get("default") or "cracker"


#: What the docker CLI is given of the caller's environment when a secret
#: travels by name (``run_with_docker(secret_env=...)``): what it needs to
#: find its daemon and its config, and nothing a person exported for
#: anything else.
_DOCKER_VARIABLES = ("PATH", "HOME", "LANG", "TMPDIR", "USER")


def docker_environment(environ) -> "dict[str, str]":
    """The docker CLI's environment when a secret is passed by name."""
    return {name: value for name, value in environ.items()
            if name in _DOCKER_VARIABLES or name.startswith(("LC_", "DOCKER_"))}


def run_with_docker(
    path: str = ".",
    build_first: bool = True,
    network: str | None = None,
    expose: bool = True,
    name: str | None = None,
    timeout: "float | None" = None,
    env: "dict[str, str] | None" = None,
    restart: "str | None" = "unless-stopped",
    host_port: "int | None" = None,
    secret_env: "dict[str, str] | None" = None,
) -> None:
    """Build (optionally) and start a function project's container, detached.

    *timeout* (seconds) bounds each docker subprocess so a stalled build/start
    fails loudly instead of hanging forever; None keeps the old unbounded
    behaviour. The container itself is started with ``-d`` (detached), so this
    returns as soon as it is running, not when it stops.

    *env* is passed to the container as ``-e NAME=VALUE``. It was added so a
    function could be handed ``WORKPEG_PK`` for its calls back into the
    Tables API, but the Tables API refuses that key: the dashboard's
    ``WORKPEG_PK`` is signed by the registry, which the API cannot verify. A
    function authenticates those calls with the token the platform mints
    per invocation and puts in ``context["token"]`` (docs/tables.md,
    "Backend access from a function"). *env* remains for anything else a
    local container needs.

    **Values are secrets.** They are passed as arguments to ``docker run``,
    which means anyone who can read the process list on the host can read
    them; that is a property of docker's own interface, not of this call, and
    it is the reason the value should be a SHORT-LIVED MINTED token rather
    than a developer's long-lived one. Nothing here logs *env*, and callers
    should keep it out of their own logs too.

    *secret_env* is for a value that must not be in the process list at
    all: docker is given ``-e NAME`` alone, and the value in its own
    environment, which is then exactly the parent's ``PATH``, ``HOME``,
    ``LANG``, the ``LC_*``, ``TMPDIR`` and ``DOCKER_*`` variables, and
    *secret_env*. No ``WORKPEG_PK`` reaches docker that way.

    *restart* is docker's ``--restart`` policy; ``None`` runs the container
    with ``--rm`` instead, removed when it stops and never restarted, which
    is how a dev function's runner starts one. *host_port* publishes the
    container's port on another loopback port.
    """
    project_path = Path(path).resolve()

    validate_function_project(project_path)

    cfg = load_function_config(project_path)
    port = cfg.get("runtime", {}).get("docker", {}).get("port", 8000)

    image = build_image(path, timeout=timeout) if build_first else (
        cfg.get("build", {}).get("image") or project_path.name
    )

    cmd = ["docker", "run", "-d"]

    if restart is None:
        cmd.append("--rm")

    if name:
        cmd += ["--name", name]

    if expose:
        # Publish to LOOPBACK only — a locally-run function's /invoke shouldn't
        # be reachable from the LAN. (The deployed runtime binds 0.0.0.0 inside
        # its own managed container; this is the developer's machine.)
        cmd += ["-p", f"127.0.0.1:{host_port or port}:{port}"]

    if network:
        cmd += ["--network", network]

    # Before --restart and before the image, because docker reads options
    # only up to the image name: anything after it is the container's own
    # argv, so an -e placed there would be handed to the entrypoint instead
    # of setting a variable.
    for key, value in (env or {}).items():
        cmd += ["-e", f"{key}={value}"]

    docker_env = None
    if secret_env:
        docker_env = docker_environment(os.environ)
        for key, value in secret_env.items():
            cmd += ["-e", key]
            docker_env[key] = value

    if restart is not None:
        cmd += ["--restart", restart]

    cmd.append(image)

    kwargs = {"check": True, "timeout": timeout}
    if docker_env is not None:
        kwargs["env"] = docker_env
    try:
        subprocess.run(cmd, **kwargs)
    except FileNotFoundError as exc:
        raise RuntimeError(
            "Docker not found. Install Docker Desktop or ensure the 'docker' "
            "command is on your PATH."
        ) from exc
    except subprocess.TimeoutExpired as exc:
        raise RuntimeError(
            f"Docker run timed out after {timeout}s."
        ) from exc
    except subprocess.CalledProcessError as exc:
        raise RuntimeError(
            f"Docker run failed (exit {exc.returncode}). "
            "Check the output above for details."
        ) from exc


#: What ``--with cracker`` says. Firecracker is where Workpeg will run
#: functions; there is nothing local to start.
CRACKER_UNAVAILABLE = (
    "cracker runs on Workpeg's engine, which is not available yet; use "
    "--with docker.")


def run_with_cracker(path: str = ".") -> None:
    raise NotImplementedError(CRACKER_UNAVAILABLE)


def main(argv=None) -> None:
    import argparse

    parser = argparse.ArgumentParser(prog="workpeg run")
    parser.add_argument("--with", dest="with_runtime", choices=["docker", "cracker"])
    parser.add_argument("--path", default=".")
    parser.add_argument("--no-build", action="store_true")
    parser.add_argument("--network", default=None)
    parser.add_argument("--name", default=None)
    parser.add_argument("--no-expose", action="store_true")
    args = parser.parse_args(argv or [])

    cfg = load_function_config(args.path)
    runtime = resolve_runtime(args.with_runtime, cfg)

    if runtime == "docker":
        run_with_docker(
            path=args.path,
            build_first=not args.no_build,
            network=args.network,
            expose=not args.no_expose,
            name=args.name,
        )
        return

    if runtime == "cracker":
        run_with_cracker(path=args.path)
        return

    raise ValueError(f"Unsupported runtime: {runtime}")
